import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_hardswish_relu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_hardswish_relu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        // HardSwish
        float t = x + 3.0f;
        t = t < 0.0f ? 0.0f : (t > 6.0f ? 6.0f : t);
        float hw = x * (t / 6.0f);
        // ReLU
        output[idx] = hw < 0.0f ? 0.0f : hw;
    }
}

torch::Tensor fused_hardswish_relu_cuda(torch::Tensor x) {
    auto out = torch::zeros_like(x);
    int size = x.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_hardswish_relu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

fused_hardswish_relu_cpp_source = r"""
torch::Tensor fused_hardswish_relu_cuda(torch::Tensor x);
"""

fused_hardswish_relu = load_inline(
    name="fused_hardswish_relu",
    cpp_sources=fused_hardswish_relu_cpp_source,
    cuda_sources=fused_hardswish_relu_source,
    functions=["fused_hardswish_relu_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Model that performs a convolution and then applies a fused HardSwish + ReLU custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)

    def forward(self, x):
        x = self.conv(x)
        x = fused_hardswish_relu.fused_hardswish_relu_cuda(x)
        return x

def get_init_inputs():
    return [3, 16, 3]

def get_inputs():
    return [torch.randn(128, 3, 32, 32)]
